    /// <summary>Maximum number of prompt (input) tokens the model accepts</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public long? MaxPromptTokens { get; init; }

    /// <summary>Whether the model supports vision</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public bool? SupportsVision { get; init; }

    /// <summary>Policy configuration state</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public PolicyState? PolicyState { get; init; }

    /// <summary>Configuration schema describing model-specific options (e.g. thinking
    /// level). Clients present this as a form and pass the resolved values in
    /// {@link ModelSelection.config} when creating or changing sessions.</summary>
