    public List<Icon>? Icons { get; set; }

    /// <summary>Optional span within {@link CustomizationBase.uri | `uri`} when this
    /// customization is a subset of a larger file (for example, one entry
    /// in an inline `mcpServers` block of a `plugins.json` manifest).
    /// Absent when the customization covers the whole resource.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public TextRange? Range { get; set; }

    /// <summary>Additional provider-specific metadata for this customization.
    ///
    /// Mirrors the MCP `_meta` convention. Optional and opaque to the
    /// protocol; producers and consumers agree on its contents
    /// out-of-band.</summary>
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; set; }

    public CustomizationType Type { get; set; } = CustomizationType.McpServer;

    /// <summary>Explicit enablement decisions for this customization, one entry per scope
    /// that has one. This is a wire contract: producers MUST publish entries
    /// sorted by descending specificity (Session, Workspace, then Global).
    /// The agent host emits at most one Workspace entry, for the session's primary
    /// working directory. Consumers MAY treat
    /// `enablement[0]` as the decisive decision and
    /// `enablement?.[0]?.enabled ?? true` as the effective enabled value. An
    /// absent or empty array means no explicit decision exists, so the
    /// customization is enabled by default.
    ///
    /// Flows in both directions. A client publishes this alongside a customization
    /// to assert its global decision, which is authoritative for the Global scope;
    /// a client always includes its global entry, even when enabled. The host
    /// publishes the fully resolved set across all scopes, and consumers derive
    /// the effective enabled value from that set.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public List<CustomizationEnablement>? Enablement { get; set; }

    /// <summary>Current lifecycle state of the MCP server.</summary>
    public required McpServerState State { get; set; }

    /// <summary>An `mcp://`-protocol channel the client uses to side-channel traffic
    /// into the upstream MCP server itself. The channel is NOT a fresh raw MCP
    /// connection: it piggybacks on the AHP transport
    /// and skips the MCP `initialize` sequence.
    ///
    /// The agent host MAY only serve a subset of MCP on this
    /// channel; the served subset is described by domain-specific
    /// capabilities such as those in
    /// {@link McpServerCustomizationApps.capabilities}.
    ///
    /// The channel URI SHOULD be stable across the server's lifetime, but
    /// the agent host MAY change it (for example across a restart) and
    /// MAY only expose it while the server is in
    /// {@link McpServerStatus.Ready | `Ready`}. Absence means no
    /// side-channel is currently available.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Channel { get; set; }

    /// <summary>MCP App support. This property SHOULD be advertised for MCP servers
    /// which support apps.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public McpServerCustomizationApps? McpApp { get; set; }
}

/// <summary>Information from the agent host needed to render MCP Apps served
/// by this MCP server.</summary>
public sealed record McpServerCustomizationApps
{
    /// <summary>The subset of MCP App
    /// [`HostCapabilities`](https://github.com/modelcontextprotocol/ext-apps/blob/main/specification/draft/apps.mdx)
    /// the AHP host can satisfy for Views backed by this server. The
    /// client feeds these straight through into the `hostCapabilities` of
    /// the `ui/initialize` response delivered to the View.</summary>
    public required AhpMcpUiHostCapabilities Capabilities { get; init; }
}

/// <summary>The subset of MCP App
/// [`HostCapabilities`](https://github.com/modelcontextprotocol/ext-apps/blob/main/specification/draft/apps.mdx)
/// an AHP host can derive from the upstream MCP server (and from AHP's own
/// forwarding plumbing). Advertised on
/// {@link McpServerCustomizationApps.capabilities} so clients can pass it
/// through into the `hostCapabilities` of the `ui/initialize` response
/// delivered to an MCP App View.
///
/// Field names mirror the MCP Apps spec exactly, so the AHP-side producer
/// can pass them straight through into the `hostCapabilities` of the
/// `ui/initialize` response delivered to the View.
///
/// Capabilities outside this set (`openLinks`, `downloadFile`, `sandbox`,
/// `experimental`) are decided locally by whichever AHP client renders the
/// View and are NOT part of this AHP-level advertisement — only the
/// server-derived subset is.
///
/// An agent host MUST only advertise a capability when it actually accepts the
/// corresponding methods/notifications on the `mcp://` channel:
///
/// - {@link serverTools}: host proxies `tools/list` and `tools/call` to
///   the MCP server. When `listChanged` is `true`, the host also forwards
///   `notifications/tools/list_changed`.
/// - {@link serverResources}: host proxies `resources/read`,
///   `resources/list`, and `resources/templates/list` to the MCP server.
///   When `listChanged` is `true`, the host also forwards
///   `notifications/resources/list_changed`.
/// - {@link logging}: host accepts `notifications/message` log entries
///   from the App and forwards them via `mcpNotification` (and forwards
///   `logging/setLevel` calls to the server).
/// - {@link sampling}: host serves `sampling/createMessage` via
///   `mcpMethodCall`. When `sampling.tools` is present, the host also
///   accepts SEP-1577 `tools` / `toolChoice` / `tool_use` content blocks
///   inside `CreateMessageRequest`.</summary>
public sealed record AhpMcpUiHostCapabilities
{
    /// <summary>Producer proxies the MCP `tools/*` methods to the upstream server.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public JsonElement? ServerTools { get; init; }

    /// <summary>Producer proxies the MCP `resources/*` methods to the upstream server.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public JsonElement? ServerResources { get; init; }

    /// <summary>Producer accepts `notifications/message` log entries from the App via `mcpNotification`.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Logging { get; init; }

    /// <summary>Producer serves `sampling/createMessage` via `mcpMethodCall`.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public JsonElement? Sampling { get; init; }
}

/// <summary>Server is registered with the host but has not yet started.</summary>
public sealed record McpServerStartingState
{
    public McpServerStatus Kind { get; init; } = McpServerStatus.Starting;
}

/// <summary>Server is running and serving requests.</summary>
public sealed record McpServerReadyState
{
    public McpServerStatus Kind { get; init; } = McpServerStatus.Ready;
}

/// <summary>A pre-registered OAuth client that clients use instead of dynamic client
/// registration when resolving an MCP authentication challenge.</summary>
public sealed record McpOAuthClient
{
    /// <summary>OAuth client identifier registered with the authorization server.</summary>
    public required string ClientId { get; init; }

    /// <summary>OAuth client secret for a confidential client. Absence means the client is
    /// public and uses a secretless flow such as authorization code with PKCE.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? ClientSecret { get; init; }
}

/// <summary>Reusable MCP authentication challenge — the RFC 9728 discovery info a
/// client needs to obtain a token and push it via the `authenticate` command.
/// Deliberately carries **no token**: this describes what is being asked for,
/// never the bearer token itself.
///
/// Shared by two independent state machines that describe the same OAuth
/// challenge from different vantage points:
///
/// - {@link McpServerAuthRequiredState} — the MCP server itself cannot serve
///   *any* request until the client authenticates.
/// - {@link ToolCallAuthRequiredState} — a specific in-flight tool call is
///   paused pending authentication (typically
///   {@link McpAuthRequiredReason.InsufficientScope} step-up auth
///   mid-execution). The server state and the tool-call state remain
///   separate on purpose: the server saying "I need auth" and a tool
///   invocation saying "I am waiting on that auth" are different facts that
///   can be true independently.</summary>
public sealed record McpAuthRequirement
{
    /// <summary>Why authentication is required.</summary>
    public McpAuthRequiredReason Reason { get; init; }

    /// <summary>Pre-registered OAuth client to use for authorization. When present, clients
    /// MUST use these credentials instead of dynamic client registration.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public McpOAuthClient? OauthClient { get; init; }

    /// <summary>RFC 9728 Protected Resource Metadata. The `resource` field is the
    /// canonical MCP server URI per RFC 8707, used as the OAuth `resource`
    /// indicator. `authorization_servers` is REQUIRED by the MCP
    /// authorization spec.</summary>
    public required ProtectedResourceMetadata Resource { get; init; }

    /// <summary>Scopes required for the current challenge, parsed from the
    /// `WWW-Authenticate: Bearer scope="…"` header (or `scopes_supported`
    /// fallback). Authoritative for the next authorization request — clients
    /// MUST NOT assume any subset/superset relationship to
    /// `resource.scopes_supported`.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public List<string>? RequiredScopes { get; init; }

    /// <summary>Human-readable hint, typically from the OAuth `error_description`.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Description { get; init; }
}

/// <summary>Server is reachable but cannot serve requests until the client
/// authenticates. Mirrors the discovery flow defined by
/// [RFC 9728](https://datatracker.ietf.org/doc/html/rfc9728)
/// (Protected Resource Metadata) and the OAuth 2.1 / RFC 6750 challenge
/// semantics required by the MCP authorization spec.
///
/// Clients react to this state by calling the existing `authenticate`
/// command with the {@link ProtectedResourceMetadata.resource | resource}
/// carried here. There is **no** `notify/authRequired` notification for
/// MCP servers — the action stream is the single source of truth.
///
/// When the transition is triggered by a request issued during a turn
/// — most commonly
/// {@link McpAuthRequiredReason.InsufficientScope | `InsufficientScope`}
/// surfacing mid-tool-call — the host SHOULD also raise
/// {@link SessionStatus.InputNeeded} on the session so the block is
/// visible at the summary level. Clients SHOULD watch this status on
/// any MCP server backing a running tool call and surface an explicit
/// affordance (e.g. a "grant additional access" prompt) tied to that
/// tool call, rather than relying on the user to notice the
/// customization’s status badge.</summary>
public sealed record McpServerAuthRequiredState
{
    /// <summary>Why authentication is required.</summary>
    public McpAuthRequiredReason Reason { get; init; }

    /// <summary>Pre-registered OAuth client to use for authorization. When present, clients
    /// MUST use these credentials instead of dynamic client registration.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public McpOAuthClient? OauthClient { get; init; }

    /// <summary>RFC 9728 Protected Resource Metadata. The `resource` field is the
    /// canonical MCP server URI per RFC 8707, used as the OAuth `resource`
    /// indicator. `authorization_servers` is REQUIRED by the MCP
    /// authorization spec.</summary>
    public required ProtectedResourceMetadata Resource { get; init; }

    /// <summary>Scopes required for the current challenge, parsed from the
    /// `WWW-Authenticate: Bearer scope="…"` header (or `scopes_supported`
    /// fallback). Authoritative for the next authorization request — clients
    /// MUST NOT assume any subset/superset relationship to
    /// `resource.scopes_supported`.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public List<string>? RequiredScopes { get; init; }

    /// <summary>Human-readable hint, typically from the OAuth `error_description`.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Description { get; init; }

    public McpServerStatus Kind { get; init; } = McpServerStatus.AuthRequired;
}

/// <summary>Server failed to start, crashed, or otherwise transitioned to a
/// non-recoverable error. Use {@link McpServerStatus.AuthRequired}
/// for authentication failures.</summary>
public sealed record McpServerErrorState
{
    public McpServerStatus Kind { get; init; } = McpServerStatus.Error;

    /// <summary>Error details.</summary>
    public required ErrorInfo Error { get; init; }
}

/// <summary>Server has been shut down. The host MAY remove the server from the
/// session entirely shortly after this state.</summary>
public sealed record McpServerStoppedState
{
    public McpServerStatus Kind { get; init; } = McpServerStatus.Stopped;
}

public sealed record ToolCallClientContributor
{
    public ToolCallContributorKind Kind { get; init; } = ToolCallContributorKind.Client;

    /// <summary>If this tool is provided by a client, the `clientId` of the owning client.
    /// Absent for server-side tools.
    ///
    /// When set, the identified client is responsible for executing the tool and
    /// dispatching `chat/toolCallComplete` with the result.</summary>
    public required string ClientId { get; init; }
}

public sealed record ToolCallMcpContributor
{
    public ToolCallContributorKind Kind { get; init; } = ToolCallContributorKind.MCP;

    /// <summary>Customization ID of the corresponding MCP server in {@link SessionState.customizations}.</summary>
    public required string CustomizationId { get; init; }
}

/// <summary>Describes a file modification with before/after state and diff metadata.
///
/// Supports creates (only `after`), deletes (only `before`), renames/moves
/// (different `uri` in `before` and `after`), and edits (same `uri`, different content).</summary>
public sealed record FileEdit
{
    /// <summary>The file state before the edit. Absent for file creations or for in-place file edits.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public JsonElement? Before { get; init; }

    /// <summary>The file state after the edit. Absent for file deletions.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public JsonElement? After { get; init; }

    /// <summary>Optional diff display metadata</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public JsonElement? Diff { get; init; }
}

/// <summary>Lightweight terminal metadata exposed on the root state.</summary>
public sealed record TerminalInfo
{
    /// <summary>Terminal URI (subscribable for full terminal state)</summary>
    public required string Resource { get; init; }

    /// <summary>Human-readable terminal title</summary>
    public required string Title { get; init; }

    /// <summary>Who currently holds this terminal</summary>
    public required TerminalClaim Claim { get; init; }

    /// <summary>Current terminal process lifecycle.</summary>
    public required TerminalLifecycleState Lifecycle { get; init; }
}

/// <summary>A terminal claimed by a connected client.</summary>
public sealed record TerminalClientClaim
{
    /// <summary>Discriminant</summary>
    public TerminalClaimKind Kind { get; init; } = TerminalClaimKind.Client;

    /// <summary>The `clientId` of the claiming client</summary>
    public required string ClientId { get; init; }
}

/// <summary>A terminal claimed by a session, optionally scoped to a specific turn or tool call.</summary>
public sealed record TerminalSessionClaim
{
    /// <summary>Discriminant</summary>
    public TerminalClaimKind Kind { get; init; } = TerminalClaimKind.Session;

    /// <summary>Session URI that claimed the terminal</summary>
    public required string Session { get; init; }

    /// <summary>Chat URI that claimed the terminal.</summary>
    public required string Chat { get; init; }

    /// <summary>Optional turn identifier within the chat.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? TurnId { get; init; }

    /// <summary>Optional tool call identifier within the turn</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? ToolCallId { get; init; }
}

/// <summary>Full state for a single terminal, loaded when a client subscribes to the terminal's URI.</summary>
public sealed class TerminalState
{
    /// <summary>Human-readable terminal title</summary>
    public required string Title { get; set; }

    /// <summary>Current working directory of the terminal process</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Cwd { get; set; }

    /// <summary>Terminal width in columns</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public long? Cols { get; set; }

    /// <summary>Terminal height in rows</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public long? Rows { get; set; }

    /// <summary>Typed content parts, replacing the flat `content: string`.
    ///
    /// Naive consumers that only need the raw VT stream can reconstruct it with:
    ///   `content.map(p =&gt; p.type === 'command' ? p.output : p.value).join('')`
    ///
    /// Consumers that need command boundaries can filter by part type.</summary>
    public required List<TerminalContentPart> Content { get; set; }

    /// <summary>Current terminal process lifecycle.</summary>
    public required TerminalLifecycleState Lifecycle { get; set; }

    /// <summary>Who currently holds this terminal</summary>
    public required TerminalClaim Claim { get; set; }

    /// <summary>Whether this terminal emits `terminal/commandExecuted` and
    /// `terminal/commandFinished` actions and populates `command`-typed parts.
    ///
    /// Clients MUST check this flag before relying on command detection.
    /// Do NOT use the presence of a `command` part as a feature flag — parts
    /// are absent in the normal idle state.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public bool? SupportsCommandDetection { get; set; }

    /// <summary>Whether this terminal-style resource is backed by a pseudoterminal.
    /// When `false`, output is plain text and clients do not need to parse
    /// VT sequences.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public bool? IsPty { get; set; }
}

/// <summary>Unstructured terminal output — content before, between, or after commands,
/// or from terminals that do not support command detection.</summary>
public sealed class TerminalUnclassifiedPart
{
    public string Type { get; set; } = "unclassified";

    /// <summary>Accumulated VT output. Appended to by `terminal/data` when no command is executing.</summary>
    public required string Value { get; set; }
}

/// <summary>A single command: its command line and the output it produced.
///
/// While `isComplete` is false the command is still executing; `output` grows
/// as `terminal/data` actions arrive. At `terminal/commandFinished` the part
/// is mutated in-place with `isComplete: true` and the completion metadata.</summary>
public sealed class TerminalCommandPart
{
    public string Type { get; set; } = "command";

    /// <summary>Stable id matching the `commandId` on the corresponding
    /// `terminal/commandExecuted` and `terminal/commandFinished` actions.</summary>
    public required string CommandId { get; set; }

    /// <summary>The command line submitted to the shell.</summary>
    public required string CommandLine { get; set; }

    /// <summary>Accumulated VT output. Appended to by `terminal/data` while `isComplete`
    /// is false. Shell integration escape sequences are stripped by the server.</summary>
    public required string Output { get; set; }

    /// <summary>Unix timestamp (ms) when execution started, as reported by the server.</summary>
    public long Timestamp { get; set; }

    /// <summary>Whether the command has finished.</summary>
    public bool IsComplete { get; set; }

    /// <summary>Shell exit code. Set at completion. `undefined` if unknown.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public long? ExitCode { get; set; }

    /// <summary>Wall-clock duration in milliseconds. Set at completion.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public long? DurationMs { get; set; }
}

public sealed record UsageInfo
{
    /// <summary>Input tokens consumed</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public long? InputTokens { get; init; }

    /// <summary>Output tokens generated</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public long? OutputTokens { get; init; }

    /// <summary>Model used</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Model { get; init; }

    /// <summary>Tokens read from cache</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public long? CacheReadTokens { get; init; }

    /// <summary>Additional provider-specific metadata for this usage report.
    /// Clients MAY look for well-known optional keys here to provide enhanced UI.</summary>
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; init; }
}

public sealed record ErrorInfo
{
    /// <summary>Error type identifier</summary>
    public required string ErrorType { get; init; }

    /// <summary>Human-readable error message</summary>
    public required string Message { get; init; }

    /// <summary>Stack trace</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Stack { get; init; }

    /// <summary>Additional provider-specific metadata for this error.
    /// Clients MAY look for well-known optional keys here to provide enhanced UI
    /// (e.g. a structured chat fetch error for richer, localized messaging).</summary>
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; init; }
}

/// <summary>A point-in-time snapshot of a subscribed resource's state, returned by
/// `initialize`, `reconnect`, and `subscribe`.</summary>
public sealed record Snapshot
{
    /// <summary>The subscribed channel URI (e.g. `ahp-root://`, `ahp-session:/&lt;uuid&gt;`, or `ahp-chat:/&lt;uuid&gt;`)</summary>
    public required string Resource { get; init; }

    /// <summary>The current state of the resource</summary>
    public required SnapshotState State { get; init; }

    /// <summary>The `serverSeq` at which this snapshot was taken. Subsequent actions will have `serverSeq &gt; fromSeq`.</summary>
    public long FromSeq { get; init; }
}

/// <summary>Catalogue entry describing one changeset the server can produce for a
/// session.
///
/// Catalogue entries are intentionally lightweight — just enough to render a
/// chip or list row without subscribing. Full per-changeset detail
/// ({@link ChangesetState}) lives on the subscribable URI obtained by
/// expanding {@link uriTemplate}.</summary>
public sealed record Changeset
{
    /// <summary>Human-readable label, e.g. `"Uncommitted Changes"`.</summary>
    public required string Label { get; init; }

    /// <summary>RFC 6570 URI template. Clients parse the variables directly out of the
    /// template using the standard `{name}` syntax — they are not redeclared
    /// here.
    ///
    /// Only the following template shapes are defined by this protocol; any
    /// other variable name MUST be ignored by clients (there is no
    /// protocol-defined way to obtain values for unknown variables):
    ///
    /// | Variables in template                       | Meaning                                                                              |
    /// | ------------------------------------------- | ------------------------------------------------------------------------------------ |
    /// | _(none)_                                    | A static, session-wide changeset. The template is itself a subscribable URI.         |
    /// | `{turnId}`                                  | Per-turn slice. Expand with a `Turn.id` from the session.                            |
    /// | `{originalTurnId}` and `{modifiedTurnId}`   | Diff between two turns. Both variables MUST be present.                              |
    ///
    /// Future protocol versions MAY add new well-known variables.</summary>
    public required string UriTemplate { get; init; }

    /// <summary>Optional longer description.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Description { get; init; }

    /// <summary>Advisory hint describing what kind of changeset this is, so clients can
    /// group, sort, or render an appropriate icon without parsing
    /// {@link uriTemplate}. Recognized values include:
    ///
    /// - `'session'`: a static, session-wide changeset covering all changes the
    ///   agent has produced in this session.
    /// - `'branch'`: changes relative to a base branch (e.g. a feature branch
    ///   diffed against `main`).
    /// - `'uncommitted'`: the workspace's current uncommitted changes.
    /// - `'turn'`: changes produced by a single turn. Typically paired with a
    ///   `{turnId}` variable in {@link uriTemplate}.
    /// - `'compare-turns'`: a diff between two turns. Typically paired with
    ///   `{originalTurnId}` and `{modifiedTurnId}` variables in
    ///   {@link uriTemplate}.
    ///
    /// Implementations MAY provide additional values; clients SHOULD fall back
    /// to a reasonable default when an unknown value is encountered.</summary>
    public required string ChangeKind { get; init; }

    /// <summary>Optional capability declarations for this changeset. Absent (or an empty
    /// object) means the changeset advertises no optional capabilities.
    ///
    /// Because the catalogue entry is delivered up-front on
    /// {@link ChangesetState | the session's changeset list}, clients can decide
    /// whether to surface capability-gated UI (such as review checkboxes) without
    /// first subscribing to the changeset URI. Mirrors the presence-flag
    /// convention of `ClientCapabilities`.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ChangesetCapabilities? Capabilities { get; init; }
}

/// <summary>Optional capabilities a changeset advertises on its catalogue
/// {@link Changeset} entry.
///
/// Each field is a presence flag: an empty object `{}` means "supported",
/// absence means "not supported". Sub-fields on individual capabilities are
/// reserved for future per-capability options.</summary>
public sealed record ChangesetCapabilities
{
    /// <summary>The changeset supports the per-file **review** workflow. When declared,
    /// clients MAY surface a GitHub-style "Viewed" toggle per file and dispatch
    /// {@link ChangesetFilesReviewChangedAction | `changeset/filesReviewChanged`} to
    /// set each file's {@link ChangesetFile.reviewed} flag. Clients that omit
    /// handling MUST treat the changeset as non-reviewable.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Review { get; init; }
}

/// <summary>Full state for a single changeset, returned when a client subscribes to
/// an expanded changeset URI.
///
/// The client already knows the URI it subscribed to, so this state does
/// not redundantly carry it (or the catalogue's `id`, `label`, etc.).
/// Aggregate counts (`additions`, `deletions`, `files`) are likewise
/// omitted: clients trivially compute them from `files[].edit.diff`.</summary>
public sealed class ChangesetState
{
    /// <summary>Computation lifecycle.</summary>
    public ChangesetStatus Status { get; set; }

    /// <summary>Present iff `status === ChangesetStatus.Error`.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ErrorInfo? Error { get; set; }

    /// <summary>Files in this changeset, keyed by {@link ChangesetFile.id}.</summary>
    public required List<ChangesetFile> Files { get; set; }

    /// <summary>Operations the client may invoke against this changeset. Omit when no
    /// operations are available.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public List<ChangesetOperation>? Operations { get; set; }
}

/// <summary>One file entry within a {@link ChangesetState}.</summary>
public sealed record ChangesetFile
{
    /// <summary>Stable identifier within the changeset. Typically `after.uri`
    /// (or `before.uri` for deletions).</summary>
    public required string Id { get; init; }

    /// <summary>Reuses the existing {@link FileEdit} shape. Clients derive line
    /// additions, deletions, and rename/create/delete semantics from this.</summary>
    public required FileEdit Edit { get; init; }

    /// <summary>Whether a reviewer has marked this file as reviewed (the GitHub-style
    /// "Viewed" checkbox). Absent is equivalent to `false` — clients MUST treat
    /// a missing value as not-yet-reviewed.
    ///
    /// Requires the changeset to advertise {@link ChangesetCapabilities.review}.
    /// Clients toggle it by dispatching
    /// {@link ChangesetFilesReviewChangedAction | `changeset/filesReviewChanged`};
    /// the server MAY also originate it (e.g. an agent self-reviewing its own
    /// output).
    ///
    /// There is no content version in the protocol, so review is **not** reset
    /// automatically when a file's contents change under a stable id. The server,
    /// which is the authority on what changed, resets review explicitly — either
    /// by re-emitting the file (via {@link ChangesetFileSetAction} or
    /// {@link ChangesetContentChangedAction}) without `reviewed: true`, or by
    /// dispatching `changeset/filesReviewChanged` with `reviewed: false`.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public bool? Reviewed { get; init; }

    /// <summary>Server-defined opaque metadata, surfaced to operations and tooling
    /// but not interpreted by the protocol.</summary>
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; init; }
}

/// <summary>A server-declared invokable verb the client can run against a
/// changeset, a file, or a range — `"stage"`, `"revert"`, `"create-pr"`,
/// and so on.
///
/// The term "operation" is used deliberately to avoid colliding with the
/// protocol-level [Actions](/guide/actions) that mutate state.</summary>
public sealed class ChangesetOperation
{
    /// <summary>Stable identifier, unique within this changeset.</summary>
    public required string Id { get; set; }

    /// <summary>Human-readable button/menu label.</summary>
    public required string Label { get; set; }

    /// <summary>Optional longer description shown on hover or in tooltips.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Description { get; set; }

    /// <summary>Where this operation can be invoked.</summary>
    public required List<ChangesetOperationScope> Scopes { get; set; }

    /// <summary>Optional confirmation prompt to show before invoking. When present,
    /// the client MUST display this message to the user (typically in a
    /// confirmation dialog) and only invoke the operation after the user
    /// accepts. The presence of this field also signals that the operation
    /// is destructive — clients SHOULD style the affirmative button
    /// accordingly (e.g. with a warning colour).</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public StringOrMarkdown? Confirmation { get; set; }

    /// <summary>Optional generic icon hint, e.g. `"check"`, `"trash"`.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Icon { get; set; }

    /// <summary>Optional group identifier, used to group related operations together.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Group { get; set; }

    /// <summary>Current execution status. The server sets
    /// {@link ChangesetOperationStatus.Running | Running} while an invocation
    /// is in flight, {@link ChangesetOperationStatus.Error | Error} when the
    /// most recent invocation failed, and
    /// {@link ChangesetOperationStatus.Idle | Idle} otherwise.
    ///
    /// Clients SHOULD reflect this state in the UI — e.g. disabling the
    /// control or showing a spinner while `Running`, and surfacing
    /// {@link error} while `Error`.</summary>
    public ChangesetOperationStatus Status { get; set; }

    /// <summary>Cause of failure. Present iff
    /// `status === ChangesetOperationStatus.Error`; otherwise omitted.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ErrorInfo? Error { get; set; }
}

/// <summary>OTLP telemetry channels the agent host emits.
///
/// Each field, when present, is either a literal channel URI or an
/// [RFC 6570](https://datatracker.ietf.org/doc/html/rfc6570) URI template
/// a client expands and then subscribes to. Absent fields indicate the host
/// does not emit that signal.
///
/// Channel URIs use the `ahp-otlp:` scheme. The scheme identifies the
/// protocol (OpenTelemetry over AHP) so clients can recognise the channel
/// type by URI alone; the host is free to choose any authority/path that
/// makes sense for its implementation. Clients MUST treat the URI as
/// opaque (apart from expanding any well-known template variables defined
/// below) and subscribe with the resulting concrete URI.
///
/// Payloads delivered on these channels are OTLP/JSON values — see
/// [opentelemetry-proto](https://github.com/open-telemetry/opentelemetry-proto)
/// for the wire shapes (`ExportLogsServiceRequest`,
/// `ExportTraceServiceRequest`, `ExportMetricsServiceRequest`).</summary>
public sealed record TelemetryCapabilities
{
    /// <summary>Channel URI (or RFC 6570 URI template) for OTLP log records
    /// (`otlp/exportLogs` notifications).
    ///
    /// The following template variables are defined by this protocol; any
    /// other variable name MUST be ignored by clients (there is no
    /// protocol-defined way to obtain values for unknown variables):
    ///
    /// | Variables in template | Meaning                                                                                                 |
    /// | --------------------- | ------------------------------------------------------------------------------------------------------- |
    /// | _(none)_              | The host does not support subscriber-side severity filtering. The template is itself a subscribable URI. |
    /// | `{level}`             | Minimum OTLP severity to deliver. Expand to one of the [OTLP `SeverityNumber`](https://opentelemetry.io/docs/specs/otel/logs/data-model/#field-severitynumber) short names (case-insensitive): `trace`, `debug`, `info`, `warn`, `error`, `fatal`. The server delivers log records whose `severityNumber` falls in the corresponding band or above. |
    ///
    /// Hosts SHOULD honour the expanded `{level}`; clients MUST still filter
    /// defensively in case a host ignores the parameter. Hosts that do not
    /// advertise `{level}` deliver all severities.
    ///
    /// Future protocol versions MAY add new well-known variables (e.g. scope
    /// or attribute filters).</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Logs { get; init; }

    /// <summary>Channel URI for OTLP spans (`otlp/exportTraces` notifications). No
    /// template variables are defined by this protocol version.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Traces { get; init; }

    /// <summary>Channel URI for OTLP metric data points (`otlp/exportMetrics`
    /// notifications). No template variables are defined by this protocol
    /// version.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Metrics { get; init; }
}

/// <summary>Full state for a single resource watch, returned when a client subscribes
/// to an `ahp-resource-watch:` URI.
///
/// Watches are otherwise stateless: the watcher exists to deliver
/// {@link ResourceWatchChangedAction} events. The state carries only the
/// descriptor of what is being watched so a re-subscribing client can
/// recover the watch configuration after reconnecting.</summary>
public sealed record ResourceWatchState
{
    /// <summary>The URI being watched. For recursive watches this is the root of the
    /// subtree; for non-recursive watches this is the single file or
    /// directory.</summary>
    public required string Root { get; init; }

    /// <summary>`true` if the watcher reports changes for descendants of `root`;
    /// `false` if it only reports changes to `root` itself (and, when
    /// `root` is a directory, its direct children).</summary>
    public bool Recursive { get; init; }

    /// <summary>Optional glob patterns or paths relative to `root` to exclude from
    /// change reporting.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public JsonElement? Excludes { get; init; }

    /// <summary>Optional glob patterns or paths relative to `root` to restrict
    /// change reporting to. Omit to report every change under `root`
    /// subject to `excludes`.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public JsonElement? Includes { get; init; }
}

/// <summary>A single change observed by a resource watcher.</summary>
public sealed record ResourceChange
{
    /// <summary>The URI of the resource that changed.</summary>
    public required string Uri { get; init; }

    /// <summary>The kind of change observed.</summary>
    public ResourceChangeType Type { get; init; }
}

/// <summary>Lightweight per-session summary of the annotations channel, surfaced on
/// {@link SessionSummary.annotations} so badge UI can render annotation /
/// entry counts without subscribing to the channel itself.</summary>
public sealed record AnnotationsSummary
{
    /// <summary>The subscribable annotations channel URI for the owning session
    /// (typically `ahp-session:/&lt;uuid&gt;/annotations`). Surfaced explicitly even
    /// though it is derivable from the session URI so badge UI does not need
    /// to know the derivation rule.</summary>
    public required string Resource { get; init; }

    /// <summary>Total number of {@link Annotation} entries in the channel.</summary>
    public long AnnotationCount { get; init; }

    /// <summary>Total number of {@link AnnotationEntry} entries across every annotation.</summary>
    public long EntryCount { get; init; }
}

/// <summary>Full state for a session's annotations channel, returned when a client
/// subscribes to an `ahp-session:/&lt;uuid&gt;/annotations` URI.</summary>
public sealed record AnnotationsState
{
    /// <summary>Annotations in this channel, keyed by {@link Annotation.id}.</summary>
    public required List<Annotation> Annotations { get; init; }
}

/// <summary>Provenance of the content an annotation is anchored to.</summary>
public sealed record AnnotationOrigin
{
    /// <summary>Owning session URI.</summary>
    public required string Session { get; init; }

    /// <summary>Owning chat URI, when the annotation is scoped to a chat.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Chat { get; init; }

    /// <summary>Turn identifier within {@link chat}, when the annotation is scoped to a turn.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? TurnId { get; init; }
}

/// <summary>A conversation anchored to a specific file in a session, optionally scoped
/// to a chat and turn and narrowed to a range within that file.
///
/// {@link origin} identifies the owning session and, when available, the chat
/// and turn that produced the file version. When {@link range} is omitted the
/// annotation is anchored to the entire file.
///
/// Every annotation MUST contain at least one {@link AnnotationEntry}. An
/// {@link AnnotationsSetAction} that creates an annotation therefore carries
/// its mandatory first entry, and removing the last remaining entry collapses
/// the annotation via {@link AnnotationsRemovedAction} rather than leaving an
/// empty annotation behind.</summary>
public sealed record Annotation
{
    /// <summary>Stable identifier within the annotations channel. Assigned by the client
    /// that dispatches the creating {@link AnnotationsSetAction}.</summary>
    public required string Id { get; init; }

    /// <summary>Provenance of the content this annotation is anchored to.</summary>
    public required AnnotationOrigin Origin { get; init; }

    /// <summary>The file the annotation is anchored to.</summary>
    public required string Resource { get; init; }

    /// <summary>Range within {@link resource} the annotation is anchored to. When
    /// omitted the annotation is anchored to the entire file.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public TextRange? Range { get; init; }

    /// <summary>Whether the annotation has been resolved. Newly created annotations are
    /// always unresolved (`false`); a client marks an annotation resolved (or
    /// re-opens it) by dispatching an {@link AnnotationsUpdatedAction} carrying
    /// the updated flag (or an {@link AnnotationsSetAction} when replacing the
    /// whole annotation).</summary>
    public bool Resolved { get; init; }

    /// <summary>Entries in this annotation, in dispatch order (oldest first). MUST
    /// contain at least one entry.</summary>
    public required List<AnnotationEntry> Entries { get; init; }

    /// <summary>Producer-defined opaque metadata, surfaced to tooling but not
    /// interpreted by the protocol.</summary>
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; init; }
}

/// <summary>A single entry within an {@link Annotation}.</summary>
public sealed record AnnotationEntry
{
    /// <summary>Stable identifier within the enclosing annotation. Assigned by the client
    /// that dispatches the {@link AnnotationsEntrySetAction} (or the enclosing
    /// {@link AnnotationsSetAction}) introducing the entry.</summary>
    public required string Id { get; init; }

    /// <summary>Entry body. A bare `string` is rendered as plain text; pass
    /// `{ markdown: "…" }` to opt into Markdown rendering. See
    /// {@link StringOrMarkdown}.</summary>
    public required StringOrMarkdown Text { get; init; }

    /// <summary>Producer-defined opaque metadata, surfaced to tooling but not
    /// interpreted by the protocol.</summary>
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; init; }
}

/// <summary>Provenance recorded on a session created for an automation run.
///
/// The links let clients navigate from an ordinary session to the task-level
/// run and its durable definition. The session channel remains authoritative
/// for this session's transcript, tools, confirmations, and changes.</summary>
public sealed record AutomationSessionOrigin
{
    public SessionOriginKind Kind { get; init; } = SessionOriginKind.Automation;

    /// <summary>Owning {@link AutomationState.resource}.</summary>
    public required string Automation { get; init; }

    /// <summary>Owning {@link AutomationRunState.resource}.</summary>
    public required string Run { get; init; }
}

/// <summary>A terminal process that is still running.</summary>
public sealed record TerminalRunningLifecycleState
{
    public TerminalLifecycleStatus Status { get; init; } = TerminalLifecycleStatus.Running;
}

/// <summary>A terminal process that has exited.</summary>
public sealed record TerminalExitedLifecycleState
{
    public TerminalLifecycleStatus Status { get; init; } = TerminalLifecycleStatus.Exited;

    /// <summary>Process exit code, if the runtime reported one.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public long? ExitCode { get; init; }
}

/// <summary>A portable recurring schedule evaluated in a named time zone.
///
/// The expression uses exactly five whitespace-separated fields, in this
/// order:
///
/// | Field | Values |
/// | --- | --- |
/// | minute | `0`–`59` |
/// | hour | `0`–`23` |
/// | day of month | `1`–`31` |
/// | month | `1`–`12` or `JAN`–`DEC` |
/// | day of week | `0`–`7` or `SUN`–`SAT`; both `0` and `7` mean Sunday |
///
/// Month and weekday names are ASCII and case-insensitive. Each field accepts
/// `*`, a single value, an inclusive range (`1-5`), a comma-separated list of
/// values or ranges (`1,3,8-10`), or a step applied to `*` or a range (for
/// example, &amp;#42;/15 or `1-30/2`). A step MUST be a positive integer. AHP does
/// not support seconds, years, macros such as `@daily`, or Quartz extensions
/// such as `?`, `L`, `W`, and `#`.
///
/// Minute, hour, and month must all match. When both day-of-month and
/// day-of-week are restricted (not `*`), an occurrence matches when either day
/// field matches, following Unix cron semantics.</summary>
public sealed record AutomationSchedule
{
    /// <summary>Five-field AHP cron expression described by {@link AutomationSchedule}.</summary>
    public required string Expression { get; init; }

    /// <summary>IANA Time Zone Database identifier used to interpret the expression, for
    /// example `"UTC"` or `"Europe/Berlin"`.</summary>
    public required string TimeZone { get; init; }
}

/// <summary>Starts runs from a recurring cron schedule evaluated by the host.</summary>
public sealed record AutomationScheduleTrigger
{
    /// <summary>Identifier unique and stable within this automation definition. Recorded in
    /// {@link AutomationTriggeredRunOrigin.triggerId} when this trigger creates a
    /// run.</summary>
    public required string Id { get; init; }

    public AutomationTriggerKind Kind { get; init; } = AutomationTriggerKind.Schedule;

    /// <summary>Recurrence and time zone evaluated by the host.</summary>
    public required AutomationSchedule Schedule { get; init; }

    /// <summary>Policy for missed occurrences. Omission is equivalent to
    /// {@link AutomationMisfirePolicy.RunOnce}.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public AutomationMisfirePolicy? MisfirePolicy { get; init; }
}

/// <summary>Starts runs from events understood by the owning host.
///
/// Event trigger types, events, and configuration are discovered through
/// {@link ListAutomationTriggerDefinitionsParams |
/// listAutomationTriggerDefinitions}. The saved trigger includes the matching
/// human-readable metadata so it remains displayable without repeating
/// discovery.</summary>
public sealed record AutomationEventTrigger
{
    /// <summary>Identifier unique and stable within this automation definition. Recorded in
    /// {@link AutomationTriggeredRunOrigin.triggerId} when this trigger creates a
    /// run.</summary>
    public required string Id { get; init; }

    public AutomationTriggerKind Kind { get; init; } = AutomationTriggerKind.Event;

    /// <summary>Matches {@link AutomationTriggerDefinition.type}.</summary>
    public required string Type { get; init; }

    /// <summary>Host-normalized human-readable trigger type name.</summary>
    public required string Title { get; init; }

    /// <summary>Optional host-normalized explanation of the trigger source.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Description { get; init; }

    /// <summary>Selected events for this trigger type.
    ///
    /// Event ids carry the trigger semantics. Titles and descriptions are
    /// last-known display metadata and do not indicate current availability.</summary>
    public required List<AutomationTriggerEventDefinition> Events { get; init; }

    /// <summary>Values described by {@link AutomationTriggerDefinition.configSchema}.
    /// Clients MUST preserve unknown entries when editing other fields.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Config { get; init; }
}

/// <summary>Describes one host-defined trigger event.</summary>
public sealed record AutomationTriggerEventDefinition
{
    /// <summary>Stable event id.</summary>
    public required string Id { get; init; }

    /// <summary>Human-readable event name.</summary>
    public required string Title { get; init; }

    /// <summary>Optional longer explanation of when this event fires.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Description { get; init; }
}

/// <summary>Describes one host-defined event trigger type available for a prospective
/// automation session template.
///
/// Trigger definitions are discovery metadata, not durable automation state.
/// Hosts may return different definitions for different providers, working
/// directories, or session configuration.</summary>
public sealed record AutomationTriggerDefinition
{
    /// <summary>Stable type id stored in {@link AutomationEventTrigger.type}.</summary>
    public required string Type { get; init; }

    /// <summary>Human-readable trigger type name.</summary>
    public required string Title { get; init; }

    /// <summary>Optional longer explanation of the trigger source.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Description { get; init; }

    /// <summary>Events available for selection. Saved triggers retain their selected event descriptors.</summary>
    public required List<AutomationTriggerEventDefinition> Events { get; init; }

    /// <summary>Optional schema for {@link AutomationEventTrigger.config}.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ConfigSchema? ConfigSchema { get; init; }
}

/// <summary>Template from which the host creates a fresh session for each automation run.
///
/// The host revalidates every selection when the run starts. Definitions never
/// carry credentials, confirmation decisions, or durable permission grants.</summary>
public sealed record AutomationSessionTemplate
{
    /// <summary>Provider id matching {@link AgentInfo.provider}. Omit to use the host's default provider.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Provider { get; init; }

    /// <summary>Optional model selection resolved when a run starts. Its
    /// {@link ModelSelection.id} matches a {@link SessionModelInfo.id} advertised
    /// by the selected provider.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ModelSelection? Model { get; init; }

    /// <summary>Optional custom agent selection identified by {@link AgentSelection.uri}.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public AgentSelection? Agent { get; init; }

    /// <summary>Ordered working-directory URIs for each created session, equivalent to
    /// {@link CreateSessionParams.workingDirectories}. Absence means a
    /// workspace-less session.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public List<string>? WorkingDirectories { get; init; }

    /// <summary>Session configuration values equivalent to
    /// {@link CreateSessionParams.config}, normally obtained from
    /// {@link ResolveSessionConfigResult.values}.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Config { get; init; }
}

/// <summary>Durable, client-editable definition of an automation.
///
/// A definition combines the initial automation message, the session template
/// used for each run, and zero or more automatic triggers. Run history,
/// timestamps, and currently allowed operations live on
/// {@link AutomationState} rather than in the definition.</summary>
public sealed record AutomationDefinition
{
    /// <summary>Human-readable automation name.</summary>
    public required string Title { get; init; }

    /// <summary>Initial message sent to every newly created run session. Its
    /// {@link Message.origin} kind MUST be {@link MessageKind.Automation}.</summary>
    public required Message Message { get; init; }

    /// <summary>Template used to create fresh sessions for each run.</summary>
    public required AutomationSessionTemplate Session { get; init; }

    /// <summary>Whether automatic triggers may create runs. Manual runs remain available
    /// whenever {@link AutomationOperation.Run} is advertised.</summary>
    public bool Enabled { get; init; }

    /// <summary>Automatic triggers. An empty list means manual-only.</summary>
    public required List<AutomationTrigger> Triggers { get; init; }

    /// <summary>Opaque implementation-defined metadata. Clients MUST preserve unknown
    /// entries when updating the definition.</summary>
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; init; }
}

/// <summary>Partial replacement of editable {@link AutomationDefinition} fields.
///
/// Omitted fields are unchanged. Supplied arrays and objects replace their
/// corresponding values in full; they are not merged recursively.</summary>
public sealed record AutomationDefinitionPatch
{
    /// <summary>Replacement {@link AutomationDefinition.title}.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Title { get; init; }

    /// <summary>Replacement {@link AutomationDefinition.message}.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Message? Message { get; init; }

    /// <summary>Replacement {@link AutomationDefinition.session}. The host revalidates
    /// affected event triggers when their discovery context changes.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public AutomationSessionTemplate? Session { get; init; }

    /// <summary>Replacement {@link AutomationDefinition.enabled}.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public bool? Enabled { get; init; }

    /// <summary>Complete replacement {@link AutomationDefinition.triggers}. The host
    /// validates event ids and normalizes event-trigger titles and descriptions.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public List<AutomationTrigger>? Triggers { get; init; }

    /// <summary>Complete replacement {@link AutomationDefinition._meta}.</summary>
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; init; }
}

/// <summary>Authoritative state of one automation in the
/// {@link AutomationCatalogState.automations} catalogue.
///
/// The host owns trigger evaluation, run claims, run retention, and operation
/// availability. Clients render this state and submit actions or commands; they
/// never run a fallback scheduler for a host-owned definition.</summary>
public sealed class AutomationState
{
    /// <summary>Stable `ahp-automation:/&lt;id&gt;` resource identifier.</summary>
    public required string Resource { get; set; }

    /// <summary>Current durable definition.</summary>
    public required AutomationDefinition Definition { get; set; }

    /// <summary>Earliest schedule occurrence awaiting evaluation, as an ISO 8601 timestamp. It may be in the past while catch-up is pending.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? NextRunAt { get; set; }

    /// <summary>Newest-first retained run summaries. This is a bounded window; use
    /// {@link FetchAutomationRunsParams | fetchAutomationRuns} when
    /// {@link AutomationState.runsNextCursor} is present.</summary>
    public required List<AutomationRunSummary> Runs { get; set; }

    /// <summary>Opaque cursor passed as {@link FetchAutomationRunsParams.cursor} for the next older run-history page.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? RunsNextCursor { get; set; }

    /// <summary>Operations currently permitted for this automation.</summary>
    public required List<AutomationOperation> Operations { get; set; }

    /// <summary>Creation timestamp in ISO 8601 format.</summary>
    public required string CreatedAt { get; set; }

    /// <summary>Last definition modification timestamp in ISO 8601 format.</summary>
    public required string ModifiedAt { get; set; }

    /// <summary>Opaque host-defined state metadata.</summary>
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; set; }
}

/// <summary>Authoritative automation catalogue exposed on the `ahp-automations://`
/// channel.
///
/// A subscription snapshot contains every automation visible to the client.
/// Subsequent {@link AutomationSetAction | `automation/set`} and
/// {@link AutomationRemovedAction | `automation/removed`} actions keep the
/// catalogue synchronized and participate in normal reconnect replay.</summary>
public sealed class AutomationCatalogState
{
    /// <summary>Full automation states keyed by {@link AutomationState.resource}.</summary>
    public required List<AutomationState> Automations { get; set; }

    /// <summary>Opaque host-defined catalogue metadata.</summary>
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; set; }
}

/// <summary>Origin recorded for a client-requested manual run.</summary>
public sealed record AutomationManualRunOrigin
{
    public AutomationRunOriginKind Kind { get; init; } = AutomationRunOriginKind.Manual;
}

/// <summary>Origin recorded for a run created by one of the automation's triggers.</summary>
public sealed record AutomationTriggeredRunOrigin
{
    public AutomationRunOriginKind Kind { get; init; } = AutomationRunOriginKind.Trigger;

    /// <summary>Matches the stable {@link AutomationScheduleTrigger.id} or
    /// {@link AutomationEventTrigger.id} in the definition.</summary>
    public required string TriggerId { get; init; }

    /// <summary>Intended schedule occurrence as an ISO 8601 timestamp. Present for
    /// schedule triggers and normally absent for event triggers.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? ScheduledFor { get; init; }

    /// <summary>`true` when this is a catch-up run created by
    /// {@link AutomationMisfirePolicy.RunOnce}.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public bool? CatchUp { get; init; }

    /// <summary>Host-defined, non-secret event provenance suitable for display or audit.
    /// This is descriptive context, not an input that clients replay.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Event { get; init; }
}

/// <summary>A durable run exists but has not begun external execution.</summary>
public sealed record AutomationPendingRunLifecycle
{
    public AutomationRunStatus Status { get; init; } = AutomationRunStatus.Pending;

    /// <summary>Run creation timestamp in ISO 8601 format.</summary>
