[JsonConverter(typeof(ChatOriginConverter))]
public sealed class ChatOrigin : AhpUnion
{
    public ChatOrigin() { }
    public ChatOrigin(object? value) : base(value) { }
}

/// <summary>Chat was started by a user directly.</summary>
public sealed record ChatOriginUser
{
    public string Kind { get; init; } = "user";
}

/// <summary>Chat was forked from another chat at a specific turn.</summary>
public sealed record ChatOriginFork
{
    public string Kind { get; init; } = "fork";

    public required string Chat { get; init; }

    public required string TurnId { get; init; }
}

/// <summary>
